"use client";

import { Canvas, useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
import { OrbitControls, useGLTF } from "@react-three/drei";
import { useEffect, useMemo, type RefObject } from "react";
import * as THREE from "three";
import { islandLandmarks, type LandmarkId } from "@/content/island";

// Generated by art/island/build_island.py and exported from Blender with meshopt compression.
const ISLAND_URL = "/playground/island.glb";
// The view: from the south-east and above, like the Blender preview camera.
const VIEW = new THREE.Vector3(1, 0.82, 1).normalize();
const TARGET = new THREE.Vector3(0, -1.5, 1.5);

type SceneProps = {
  selected: LandmarkId | null;
  hovered: LandmarkId | null;
  onSelect: (id: LandmarkId) => void;
  onHover: (id: LandmarkId | null) => void;
  orbit: boolean;
  /** Label elements drawn by IslandPiece over the canvas; the scene moves them to their landmarks each frame. */
  labels: RefObject<Map<LandmarkId, HTMLElement>>;
};

type Mark = { id: LandmarkId; label: string; top: THREE.Vector3; door: THREE.Vector3 };

/** The island from Blender, with its landmarks made pickable and their label and ring points measured. */
function Island({ selected, hovered, onSelect, onHover, labels }: SceneProps) {
  const { scene } = useGLTF(ISLAND_URL, false, true);
  const invalidate = useThree((s) => s.invalidate);

  const { root, marks } = useMemo(() => {
    const root = scene.clone(true);
    root.traverse((o) => {
      const mesh = o as THREE.Mesh;
      if (!mesh.isMesh) return;
      // Ground, paths and water only receive shadows; everything standing on them also casts.
      const flat = /^(walk_ground|walk_path|water_pond|island_base|deco_(path|paving|grass|lilies|photo_spot))/.test(nameOf(o));
      mesh.castShadow = !flat;
      mesh.receiveShadow = true;
    });
    root.updateMatrixWorld(true);
    const marks: Mark[] = [];
    for (const l of islandLandmarks) {
      const obj = root.getObjectByName(l.object);
      const door = root.getObjectByName(l.door);
      if (!obj || !door) {
        if (process.env.NODE_ENV !== "production") console.warn(`Island: missing ${!obj ? l.object : l.door} in ${ISLAND_URL}`);
        continue;
      }
      obj.traverse((c) => (c.userData.landmark = l.id));
      const box = new THREE.Box3().setFromObject(obj);
      marks.push({
        id: l.id,
        label: l.label,
        top: new THREE.Vector3((box.min.x + box.max.x) / 2, box.max.y + 1.0, (box.min.z + box.max.z) / 2),
        door: door.getWorldPosition(new THREE.Vector3()),
      });
    }
    return { root, marks };
  }, [scene]);

  const active = hovered ?? selected;
  useEffect(() => invalidate(), [invalidate, active]);

  // Pin each label to the point above its landmark, on every rendered frame (camera moves, resizes).
  const v = useMemo(() => new THREE.Vector3(), []);
  useFrame(({ camera, size }) => {
    const els = labels.current;
    if (!els) return;
    for (const m of marks) {
      const el = els.get(m.id);
      if (!el) continue;
      v.copy(m.top).project(camera);
      el.style.transform = `translate(-50%, -50%) translate(${((v.x + 1) / 2) * size.width}px, ${((1 - v.y) / 2) * size.height}px)`;
      el.style.opacity = v.z < 1 ? "1" : "0";
    }
  });

  const landmarkOf = (e: ThreeEvent<PointerEvent | MouseEvent>) => (e.object.userData.landmark as LandmarkId | undefined) ?? null;

  return (
    <>
      <primitive
        object={root}
        onPointerMove={(e: ThreeEvent<PointerEvent>) => {
          const id = landmarkOf(e);
          onHover(id);
          document.body.style.cursor = id ? "pointer" : "";
        }}
        onPointerLeave={() => {
          onHover(null);
          document.body.style.cursor = "";
        }}
        onClick={(e: ThreeEvent<MouseEvent>) => {
          const id = landmarkOf(e);
          if (!id) return;
          e.stopPropagation();
          onSelect(id);
        }}
      />
      {marks.map((m) => {
        const on = m.id === active;
        return (
          <group key={m.id}>
            {/* A ring on the ground where a visitor will stand to use the landmark. */}
            <mesh position={[m.door.x, m.door.y + 0.12, m.door.z]} rotation={[-Math.PI / 2, 0, 0]} scale={on ? 1.25 : 1}>
              <ringGeometry args={[0.6, 0.82, 40]} />
              <meshBasicMaterial color="#ffffff" transparent opacity={on ? 1 : 0.65} />
            </mesh>
          </group>
        );
      })}
    </>
  );
}

/** Blender's exporter names a multi-material mesh's parts after the object; walk up to the named node. */
function nameOf(o: THREE.Object3D) {
  let n: THREE.Object3D | null = o;
  while (n && !n.name) n = n.parent;
  return n?.name ?? "";
}

/** Keeps the whole island in view: further back on tall, narrow canvases. */
function Framing() {
  const camera = useThree((s) => s.camera);
  const width = useThree((s) => s.size.width);
  const height = useThree((s) => s.size.height);
  const controls = useThree((s) => s.controls) as { target?: THREE.Vector3; update?: () => void } | null;
  const invalidate = useThree((s) => s.invalidate);
  useEffect(() => {
    const aspect = width / Math.max(height, 1);
    const distance = aspect >= 1.5 ? 70 : aspect >= 1.1 ? 82 : aspect >= 0.8 ? 104 : 130;
    camera.position.copy(TARGET).addScaledVector(VIEW, distance);
    camera.lookAt(TARGET);
    if (controls?.target) {
      controls.target.copy(TARGET);
      controls.update?.();
    }
    invalidate();
  }, [camera, width, height, controls, invalidate]);
  return null;
}

export default function IslandScene(props: SceneProps) {
  const { orbit, onHover } = props;
  return (
    <Canvas
      frameloop="demand"
      flat
      shadows
      dpr={[1, 2]}
      camera={{ fov: 30, near: 1, far: 400 }}
      gl={{ antialias: true, alpha: true }}
      onPointerLeave={() => {
        onHover(null);
        document.body.style.cursor = "";
      }}
      fallback={null}
    >
      <Framing />
      {/* Warm sky over green ground, and one low sun for long soft shadows, like the references. */}
      <hemisphereLight args={["#fff4e0", "#7d8f5c", 1.6]} />
      <directionalLight
        position={[26, 42, 14]}
        intensity={2.4}
        color="#fff1d6"
        castShadow
        shadow-mapSize={[2048, 2048]}
        shadow-camera-left={-30}
        shadow-camera-right={30}
        shadow-camera-top={30}
        shadow-camera-bottom={-30}
        shadow-camera-near={1}
        shadow-camera-far={120}
        shadow-bias={-0.0004}
        shadow-normalBias={0.05}
      />
      <Island {...props} />
      {orbit && (
        <OrbitControls
          enablePan={false}
          enableZoom={false}
          makeDefault
          enableDamping
          minPolarAngle={0.7}
          maxPolarAngle={1.15}
          minAzimuthAngle={Math.PI / 4 - 0.6}
          maxAzimuthAngle={Math.PI / 4 + 0.6}
        />
      )}
    </Canvas>
  );
}

useGLTF.preload(ISLAND_URL, false, true);
